async Task<Produit> Lire(int id)
{
    var p = await cache.Get<Produit>($"p:{id}");
    if (p is null)
    {
        p = await db.Produits.FindAsync(id);
        await cache.Set($"p:{id}", p,
            TimeSpan.FromMinutes(10));
    }
    return p;
}

